base.db.py:
class NotFound(Exception):
    pass


def find_user(users, uid):
    for u in users:
        if u['id'] == uid:
            return u
    raise NotFound(uid)

base.api.py:
from db import find_user


def profile(users, uid):
    user = find_user(users, uid)
    return {'name': user['name'], 'email': user['email']}

